'use client';

import type { Variants } from 'motion/react';
import type { HTMLAttributes } from 'react';
import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
} from 'react';
import { motion, useAnimation, useReducedMotion } from 'motion/react';

import { cn } from '@/lib/utils';

export interface HugeiconsShipIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}
interface HugeiconsShipIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

const ICON_VARIANTS: Variants = {
  normal: {
    x: 0,
    y: 0,
    rotate: 0,
    scale: 1,
    scaleX: 1,
    scaleY: 1,
    opacity: 1,
    transition: { duration: 0.18, ease: 'easeOut' },
  },
  animate: {
    x: [0, 1.2, -0.6, 0],
    y: [0, -0.35, 0, 0],
    transition: { duration: 1, ease: 'easeInOut' },
  },
};

const HugeiconsShipIcon = forwardRef<
  HugeiconsShipIconHandle,
  HugeiconsShipIconProps
>(
  (
    {
      onMouseEnter,
      onMouseLeave,
      onFocus,
      onBlur,
      className,
      size = 28,
      ...props
    },
    ref
  ) => {
    const controls = useAnimation();
    const reducedMotion = useReducedMotion();
    const sequence = useRef(0);
    const startAnimation = useCallback(() => {
      const current = ++sequence.current;
      controls.stop();
      controls.set('normal');
      if (reducedMotion) return;
      void controls.start('animate').then(() => {
        if (sequence.current === current) controls.set('normal');
      });
    }, [controls, reducedMotion]);
    const stopAnimation = useCallback(() => {
      sequence.current += 1;
      void controls.start('normal');
    }, [controls]);
    useImperativeHandle(ref, () => ({ startAnimation, stopAnimation }), [
      startAnimation,
      stopAnimation,
    ]);
    useEffect(() => {
      if (reducedMotion) {
        sequence.current += 1;
        controls.set('normal');
      }
      return () => {
        sequence.current += 1;
        controls.stop();
      };
    }, [controls, reducedMotion]);
    return (
      <div
        {...props}
        className={cn(className)}
        onMouseEnter={(event) => {
          if (!ref) startAnimation();
          onMouseEnter?.(event);
        }}
        onMouseLeave={(event) => {
          if (!ref) stopAnimation();
          onMouseLeave?.(event);
        }}
        onFocus={(event) => {
          if (!ref) startAnimation();
          onFocus?.(event);
        }}
        onBlur={(event) => {
          if (!ref) stopAnimation();
          onBlur?.(event);
        }}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
          aria-hidden="true"
          focusable="false"
        >
          <motion.g
            initial="normal"
            animate={controls}
            variants={ICON_VARIANTS}
            style={{ transformOrigin: '12px 12px' }}
          >
            <path
              d="M1.99219 21.5C3.49219 21.5 4.54253 20.5 5.49219 20.5C6.44186 20.5 7.65025 21.5113 8.49219 21.5C9.50251 21.5085 10.8526 20.5 11.9922 20.5C13.1318 20.5 14.4819 21.5085 15.4922 21.5C16.3341 21.5113 17.5425 20.5 18.4922 20.5C19.4418 20.5 20.4922 21.5 21.9922 21.5"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
            <path
              d="M5.49217 20.4999L4.51927 18.3595C3.79459 16.7653 3.43226 15.9681 3.67706 15.2258C3.92186 14.4834 4.68729 14.0582 6.21816 13.2077L10.0496 11.0791C10.9991 10.5516 11.4739 10.2878 11.9922 10.2878C12.5104 10.2878 12.9852 10.5516 13.9347 11.0791L17.7662 13.2077C19.297 14.0582 20.0625 14.4834 20.3073 15.2258C20.5521 15.9681 20.1897 16.7653 19.4651 18.3595L18.4922 20.4999"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
            <path
              d="M5.99219 13.2639V11.2361C5.99219 10.0333 5.99219 9.43184 6.29089 8.94854C6.58958 8.46523 7.1275 8.19628 8.20333 7.65836L10.2033 6.65836C11.0811 6.21945 11.5201 6 11.9922 6C12.4643 6 12.9032 6.21945 13.781 6.65836L15.781 7.65836C16.8569 8.19628 17.3948 8.46523 17.6935 8.94854C17.9922 9.43184 17.9922 10.0333 17.9922 11.2361V13.2639"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
            <path
              d="M9.99219 6.5V4.5C9.99219 4.03501 9.99219 3.80252 10.0433 3.61177C10.182 3.09413 10.5863 2.68981 11.104 2.55111C11.2947 2.5 11.5272 2.5 11.9922 2.5C12.4572 2.5 12.6897 2.5 12.8804 2.55111C13.3981 2.68981 13.8024 3.09413 13.9411 3.61177C13.9922 3.80252 13.9922 4.03501 13.9922 4.5V6.5"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);
HugeiconsShipIcon.displayName = 'HugeiconsShipIcon';
export { HugeiconsShipIcon };
